INSERT INTO syllabus_units (id, course_id, unit_no, title, topics, planned_hours) VALUES (1, 1, 1, 'Introduction & Classical Ciphers', 'Security goals, attacks, substitution and transposition ciphers', 8);
INSERT INTO syllabus_units (id, course_id, unit_no, title, topics, planned_hours) VALUES (2, 1, 2, 'Symmetric Key Cryptography', 'Block ciphers, DES, AES, modes of operation', 9);
